import { Router, type IRouter } from "express";
import {
  AskStudyMateBody,
  AskStudyMateResponse,
  GenerateStudyNotesBody,
  GenerateStudyNotesResponse,
  GenerateStudyPlanBody,
  GenerateStudyPlanResponse,
  GetStudyMateStatusResponse,
} from "@workspace/api-zod";

const router: IRouter = Router();

const demoMode = "demo" as const;

router.get("/study/status", (_req, res) => {
  res.json(
    GetStudyMateStatusResponse.parse({
      mode: demoMode,
      message:
        "Demo mode is active. Answers are sample responses generated by StudyMate's demo server.",
    }),
  );
});

router.post("/study/ask", (req, res) => {
  const parsed = AskStudyMateBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Enter a question between 2 and 2,000 characters." });
    return;
  }

  res.json(
    AskStudyMateResponse.parse({
      answer: createDemoAnswer(parsed.data.question.trim()),
      mode: demoMode,
    }),
  );
});

router.post("/study/notes", (req, res) => {
  const parsed = GenerateStudyNotesBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Enter a topic between 2 and 160 characters." });
    return;
  }

  res.json(
    GenerateStudyNotesResponse.parse({
      answer: createDemoNotes(parsed.data.topic.trim()),
      mode: demoMode,
    }),
  );
});

router.post("/study/planner", (req, res) => {
  const parsed = GenerateStudyPlanBody.safeParse(req.body);
  if (!parsed.success) {
    res
      .status(400)
      .json({ error: "Add subjects and choose 15 to 720 available minutes." });
    return;
  }

  const subjects = splitSubjects(parsed.data.subjects);
  if (subjects.length === 0) {
    res.status(400).json({ error: "Enter at least one subject to plan." });
    return;
  }

  res.json(
    GenerateStudyPlanResponse.parse({
      answer: createDemoPlan(
        subjects,
        parsed.data.availableMinutes,
      ),
      mode: demoMode,
    }),
  );
});

function createDemoAnswer(question: string): string {
  const normalized = question.toLowerCase();
  const examples: Array<[string[], string]> = [
    [
      ["mitosis and meiosis", "meiosis and mitosis"],
      "Mitosis produces two genetically identical cells for growth and repair. Meiosis produces four genetically different cells with half the chromosome number for reproduction. Both use chromosome separation, but meiosis has two rounds of division and crossing over. Memory cue: mitosis maintains; meiosis mixes and halves.",
    ],
    [
      ["photosynthesis", "chlorophyll"],
      "Photosynthesis is the process plants use to turn light energy into chemical energy. In the chloroplasts, light energy helps convert carbon dioxide and water into glucose, releasing oxygen. A useful memory cue is: light + water + carbon dioxide → sugar + oxygen.",
    ],
    [
      ["mitosis", "cell division"],
      "Mitosis makes two genetically identical daughter cells. The main stages are prophase (chromosomes condense), metaphase (line up), anaphase (separate), and telophase (new nuclei form), followed by cytokinesis. Remember: PMAT.",
    ],
    [
      ["derivative", "differentiate", "calculus"],
      "A derivative measures how quickly a function changes at a point, or the slope of its tangent line. For a power term xⁿ, the power rule gives d(xⁿ)/dx = n·xⁿ⁻¹. Check your result by asking whether it describes the function's rate of change.",
    ],
    [
      ["opportunity cost"],
      "Opportunity cost is the value of the next-best option you give up when you choose something. If you spend an hour studying economics instead of working a paid shift, the forgone pay is one part of that choice's opportunity cost. It is about the best alternative, not every possible alternative.",
    ],
    [
      ["supply", "demand", "economics"],
      "In a basic market model, demand usually falls as price rises, while supply usually rises as price rises. Their intersection is the equilibrium price and quantity. Shifts in either curve change that equilibrium; movement along a curve is caused by a price change.",
    ],
  ];
  examples[examples.length - 1][0] = ["supply", "demand"];
  const match = examples.find(([keywords]) =>
    keywords.some((keyword) => normalized.includes(keyword)),
  );

  if (match) {
    return match[1];
  }

  return `Sample study response for: “${question}”\n\nStart with a one-sentence definition, explain the key steps or causes, then add a concrete example. To check your understanding, close your notes and explain the idea in your own words. This demo answer is a study prompt, not a researched or AI-generated answer.`;
}

function createDemoNotes(topic: string): string {
  const normalized = topic.toLowerCase();
  const examples: Array<[string[], string]> = [
    [
      ["photosynthesis"],
      "CORE IDEA\nPlants convert light energy into chemical energy stored in sugars.\n\nKEY POINTS\n• Takes place in chloroplasts; chlorophyll absorbs light.\n• Light reactions use water and release oxygen.\n• The Calvin cycle uses carbon dioxide to build sugars.\n• Overall: carbon dioxide + water + light → glucose + oxygen.\n\nQUICK SELF-TEST\nWhat are the roles of light, water, and carbon dioxide?",
    ],
    [
      ["mitosis"],
      "CORE IDEA\nMitosis produces two genetically identical daughter cells.\n\nKEY POINTS\n• Prophase: chromosomes condense.\n• Metaphase: chromosomes line up.\n• Anaphase: sister chromatids separate.\n• Telophase: new nuclei form; cytokinesis divides the cell.\n• Memory cue: PMAT.\n\nQUICK SELF-TEST\nCan you name what happens in each PMAT stage?",
    ],
    [
      ["cellular respiration", "respiration"],
      "CORE IDEA\nCells transfer energy from glucose into ATP.\n\nKEY POINTS\n• Glycolysis starts in the cytoplasm and splits glucose.\n• The citric acid cycle releases carbon dioxide and transfers energy.\n• The electron transport chain uses oxygen and makes most ATP.\n• Products include ATP, carbon dioxide, and water.\n\nQUICK SELF-TEST\nWhere does glycolysis occur, and why is oxygen important?",
    ],
    [
      ["opportunity cost"],
      "CORE IDEA\nOpportunity cost is the value of the next-best alternative you give up.\n\nKEY POINTS\n• Every choice uses limited resources such as time or money.\n• Count the best forgone option, not all possible options.\n• Example: study time may mean giving up a paid work shift.\n\nQUICK SELF-TEST\nWhat is the next-best option you give up in a recent choice?",
    ],
  ];
  const example = examples.find(([keywords]) =>
    keywords.some((keyword) => normalized.includes(keyword)),
  );
  if (example) {
    return `Demo revision notes: ${topic}\n\n${example[1]}\n\nThese are sample notes, not AI-generated course content. Check details against your class materials.`;
  }

  return `Demo revision notes: ${topic}\n\nCORE IDEA\nWrite a one-sentence definition of ${topic} in your own words.\n\nKEY POINTS\n• Identify the 3–5 terms, stages, or arguments most likely to matter.\n• Connect each point to one example from class.\n• Note one common misconception or confusing comparison.\n\nQUICK SELF-TEST\nWithout looking at your notes, explain ${topic} in 30 seconds. Then write one question you still need to check against your course materials.\n\nThese are sample notes in a reusable revision format, not AI-generated course content.`;
}

function splitSubjects(subjectText: string): string[] {
  return subjectText
    .split(/,|\n|;|\s+\band\b\s+/i)
    .map((subject) => subject.trim())
    .filter(Boolean);
}

function createDemoPlan(
  allSubjects: string[],
  availableMinutes: number,
): string {
  const subjects = allSubjects.slice(0, 12);
  const baseMinutes = Math.floor(availableMinutes / subjects.length);
  let extraMinutes = availableMinutes % subjects.length;
  const blocks = subjects.map((subject, index) => {
    const minutes = baseMinutes + (extraMinutes > 0 ? 1 : 0);
    extraMinutes = Math.max(0, extraMinutes - 1);
    return `${index + 1}. ${subject} — ${minutes} min\n   Focus: review one key idea, then do a short active-recall check.`;
  });
  const moreSubjects = allSubjects.length > subjects.length;

  return `Demo revision plan · ${availableMinutes} minutes\n\n${blocks.join("\n\n")}\n\nAfter the final block, take a short break and note what to revisit. The minutes are divided evenly as a sample plan; breaks are not counted in the total.${moreSubjects ? "\n\nThis demo plan uses the first 12 subjects entered." : ""}`;
}

export default router;
